// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport android.content.Contextimport android.hardware.camera2.CameraAccessExceptionimport android.hardware.camera2.CameraManagerimport android.media.AudioManagerimport android.os.Buildimport com.roshan.persona.brain.skill.AudioStream/** * NOUS — Android Service Interfaces (Module 10 v2 — for handler testability). * * Wraps Android system services (AudioManager, CameraManager, TelecomManager) * behind interfaces so handlers can be unit-tested without Robolectric. * * Real implementations ([AndroidAudioService], [AndroidCameraService], * [AndroidAudioStateProbe]) wrap the Android system services. Tests inject * fakes ([FakeAudioService], etc. — defined in test sources). * * ## Why interfaces, not direct Android API calls? * * Android's `AudioManager` and `CameraManager` are concrete `final` classes * that require a `Context` to instantiate. Mocking them with MockK requires * `mockkClass` (slower, less type-safe). Wrapping them behind interfaces: *  - Allows pure-Kotlin unit tests (no Robolectric). *  - Documents exactly which Android APIs the handler depends on. *  - Makes it trivial to swap implementations (e.g., a "dry-run" service *    that records calls without touching hardware — useful for agent tasks). */// ──────────────────────────────────────────────────────────────────────────// Audio service (wraps AudioManager)// ──────────────────────────────────────────────────────────────────────────/** * Audio service interface — wraps the subset of [AudioManager] that Module 10 * handlers use. * * Methods are intentionally minimal — extend only when a new handler needs * a new AudioManager call. */interface AudioService {    /** Get the current volume level (0..maxVolume) for [stream]. */    fun getStreamVolume(stream: AudioStream): Int    /** Set the volume level for [stream]. Level is clamped to [0, maxVolume]. */    fun setStreamVolume(stream: AudioStream, level: Int)    /** Get the maximum volume level for [stream]. */    fun getStreamMaxVolume(stream: AudioStream): Int    /** Adjust the volume for [stream] by [delta] (negative = down, positive = up). */    fun adjustStreamVolume(stream: AudioStream, delta: Int)    /** Get the current ringer mode (NORMAL / VIBRATE / SILENT). */    fun getRingerMode(): com.roshan.persona.brain.skill.RingerMode    /** Set the ringer mode. */    fun setRingerMode(mode: com.roshan.persona.brain.skill.RingerMode)    /** Map NOUS [AudioStream] enum → Android AudioManager stream type int. */    fun streamToInt(stream: AudioStream): Int}/** * Android [AudioService] backed by [AudioManager]. */class AndroidAudioService(    private val audioManager: AudioManager,) : AudioService {    override fun getStreamVolume(stream: AudioStream): Int =        audioManager.getStreamVolume(streamToInt(stream))    override fun setStreamVolume(stream: AudioStream, level: Int) {        val max = getStreamMaxVolume(stream)        val clamped = level.coerceIn(0, max)        audioManager.setStreamVolume(streamToInt(stream), clamped, 0)    }    override fun getStreamMaxVolume(stream: AudioStream): Int =        audioManager.getStreamMaxVolume(streamToInt(stream))    override fun adjustStreamVolume(stream: AudioStream, delta: Int) {        val flag = AudioManager.FLAG_SHOW_UI        audioManager.adjustStreamVolume(streamToInt(stream), delta, flag)    }    override fun getRingerMode(): com.roshan.persona.brain.skill.RingerMode =        when (audioManager.ringerMode) {            AudioManager.RINGER_MODE_NORMAL -> com.roshan.persona.brain.skill.RingerMode.NORMAL            AudioManager.RINGER_MODE_VIBRATE -> com.roshan.persona.brain.skill.RingerMode.VIBRATE            AudioManager.RINGER_MODE_SILENT -> com.roshan.persona.brain.skill.RingerMode.SILENT            else -> com.roshan.persona.brain.skill.RingerMode.NORMAL        }    override fun setRingerMode(mode: com.roshan.persona.brain.skill.RingerMode) {        audioManager.ringerMode = when (mode) {            com.roshan.persona.brain.skill.RingerMode.NORMAL -> AudioManager.RINGER_MODE_NORMAL            com.roshan.persona.brain.skill.RingerMode.VIBRATE -> AudioManager.RINGER_MODE_VIBRATE            com.roshan.persona.brain.skill.RingerMode.SILENT -> AudioManager.RINGER_MODE_SILENT        }    }    override fun streamToInt(stream: AudioStream): Int = when (stream) {        AudioStream.MEDIA -> AudioManager.STREAM_MUSIC        AudioStream.RING -> AudioManager.STREAM_RING        AudioStream.NOTIFICATION -> AudioManager.STREAM_NOTIFICATION        AudioStream.ALARM -> AudioManager.STREAM_ALARM        AudioStream.CALL -> AudioManager.STREAM_VOICE_CALL        AudioStream.SYSTEM -> AudioManager.STREAM_SYSTEM    }}// ──────────────────────────────────────────────────────────────────────────// Audio state probe (wraps TelecomManager + AudioManager for intelligent routing)// ──────────────────────────────────────────────────────────────────────────/** * Audio state probe — checks the device's current audio-related state. * * Used by [VolumeHandler] for **intelligent stream routing** (Review 2 Elite 3): *  - If `isInCall()` → adjust VOICE_CALL stream (not MEDIA). *  - If `isMusicPlaying()` → adjust MEDIA stream. *  - Otherwise → use the stream the user specified (default MEDIA). * * Real impl ([AndroidAudioStateProbe]) wraps TelecomManager + AudioManager. */interface AudioStateProbe {    /** True if the user is currently in a phone call (off-hook). */    fun isInCall(): Boolean    /** True if any app is actively playing music/media. */    fun isMusicActive(): Boolean    /** True if the device is in silent mode (ringer = SILENT). */    fun isSilentMode(): Boolean}/** * Android [AudioStateProbe] backed by [AudioManager] + [android.telecom.TelecomManager]. */class AndroidAudioStateProbe(    private val context: Context,    private val audioManager: AudioManager,) : AudioStateProbe {    override fun isInCall(): Boolean {        return try {            val tm = context.getSystemService(android.content.Context.TELECOM_SERVICE)                as? android.telecom.TelecomManager            tm?.isInCall() ?: audioManager.mode == AudioManager.MODE_IN_CALL        } catch (t: SecurityException) {            // READ_PHONE_STATE not granted — fall back to audio mode.            audioManager.mode == AudioManager.MODE_IN_CALL        }    }    override fun isMusicActive(): Boolean = audioManager.isMusicActive    override fun isSilentMode(): Boolean =        audioManager.ringerMode == AudioManager.RINGER_MODE_SILENT}// ──────────────────────────────────────────────────────────────────────────// Camera service (wraps CameraManager torch methods)// ──────────────────────────────────────────────────────────────────────────/** * Camera service interface — wraps the subset of [CameraManager] that * [TorchHandler] uses (torch on/off + brightness on API 33+). * * ## Exception handling * * Implementations should NOT catch [CameraAccessException] — let it propagate * to the handler, which delegates to [com.roshan.persona.system.util.HardwareExceptionMapper] * for consistent error mapping. */interface CameraService {    /** True if the device has at least one camera with a flash unit (torch-capable). */    fun hasTorch(): Boolean    /** Get the camera ID of the first back-facing camera with torch capability, or null. */    fun getTorchCameraId(): String?    /**     * Turn the torch on/off for [cameraId].     *     * @throws CameraAccessException if the camera is in use, disconnected, or disabled.     */    fun setTorchMode(cameraId: String, enabled: Boolean)    /**     * Set the torch brightness level (API 33+).     *     * @param level 0.0–1.0 (0 = off, 1 = full brightness).     * @throws CameraAccessException if the camera doesn't support brightness control.     * @throws UnsupportedOperationException if the API level is below 33.     */    fun setTorchBrightnessLevel(cameraId: String, level: Float)    /** True if torch brightness control is available (API 33+). */    fun supportsBrightnessControl(): Boolean    /** Read the current torch state for [cameraId] (true = on). */    fun isTorchEnabled(cameraId: String): Boolean}/** * Android [CameraService] backed by [CameraManager]. */class AndroidCameraService(    private val cameraManager: CameraManager,) : CameraService {    @Volatile    private var cachedTorchCameraId: String? = null    @Volatile    private var cachedTorchState: Boolean = false    init {        // Register a torch-mode callback to keep cachedTorchState in sync.        // (The cache is used by isTorchEnabled to avoid a getCameraCharacteristics        // round-trip on every idempotent check.)        try {            cameraManager.registerTorchCallback(object : CameraManager.TorchCallback() {                override fun onTorchModeChanged(cameraId: String, enabled: Boolean) {                    cachedTorchState = enabled                }            }, null)        } catch (t: Throwable) {            Timber.tag("AndroidCameraService").w("Failed to register torch callback", t)        }    }    override fun hasTorch(): Boolean = getTorchCameraId() != null    override fun getTorchCameraId(): String? {        cachedTorchCameraId?.let { return it }        return try {            for (id in cameraManager.cameraIdList) {                val chars = cameraManager.getCameraCharacteristics(id)                val flashAvailable = chars.get(android.hardware.camera2.CameraCharacteristics.FLASH_INFO_AVAILABLE)                val facing = chars.get(android.hardware.camera2.CameraCharacteristics.LENS_FACING)                if (flashAvailable == true &&                    facing == android.hardware.camera2.CameraCharacteristics.LENS_FACING_BACK                ) {                    cachedTorchCameraId = id                    return id                }            }            null        } catch (e: CameraAccessException) {            Timber.tag("AndroidCameraService").w("Failed to enumerate cameras", e)            null        }    }    override fun setTorchMode(cameraId: String, enabled: Boolean) {        cameraManager.setTorchMode(cameraId, enabled)        cachedTorchState = enabled    }    override fun setTorchBrightnessLevel(cameraId: String, level: Float) {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) {            throw UnsupportedOperationException(                "Torch brightness control requires API 33+ (Tiramisu)"            )        }        // setTorchModeStrengthLevel is API 33+        val clamped = level.coerceIn(0f, 1f)        // Cast to Any to avoid NoSuchMethodError on older API levels (the method        // doesn't exist on the stubbed CameraManager below API 33).        val method = CameraManager::class.java.getMethod(            "setTorchModeStrengthLevel",            String::class.java,            Int::class.javaPrimitiveType,        )        method.invoke(cameraManager, cameraId, (clamped * 65535).toInt())    }    override fun supportsBrightnessControl(): Boolean =        Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU    override fun isTorchEnabled(cameraId: String): Boolean = cachedTorchState}